+	for id, directory := range directories {
+		byDirectory[directory] = append(byDirectory[directory], id)
+	}
+	ordered := make([]string, 0, len(byDirectory))
+	for directory := range byDirectory {
+		ordered = append(ordered, directory)
+	}
