+	}
+	defer func() {
+		if err := file.Close(); err != nil && retErr == nil {
+			retErr = fmt.Errorf("close Runner: %w", err)
+		}
+	}()
+	info, err := file.Stat()
+	if err != nil {
+		return "", fmt.Errorf("stat Runner: %w", err)
